  1	import java.util.ArrayDeque;
  2	import java.util.ArrayList;
  3	import java.util.Deque;
  4	import java.util.List;
  5	
  6	final class TopologicalSort {
  7	
  8	    private static final int SAMPLE_VERTEX_COUNT = 6;
  9	    private static final Edge[] SAMPLE_EDGES = {
 10	        edge(0, 1),
 11	        edge(1, 2),
 12	        edge(2, 3),
 13	        edge(4, 5),
 14	        edge(5, 1),
 15	        edge(5, 2)
 16	    };
 17	
 18	    private TopologicalSort() {
 19	    }
 20	
 21	    private static final class Edge {
 22	        private final int from;
 23	        private final int to;
 24	
 25	        private Edge(int from, int to) {
 26	            this.from = from;
 27	            this.to = to;
 28	        }
 29	    }
 30	
 31	    static List<Integer> topoSort(List<? extends List<Integer>> adjacencyList) {
 32	        return topologicalSort(adjacencyList);
 33	    }
 34	
 35	    static List<Integer> topologicalSort(List<? extends List<Integer>> adjacencyList) {
 36	        int vertexCount = adjacencyList.size();
 37	        int[] inDegree = calculateInDegrees(adjacencyList);
 38	        Deque<Integer> readyVertices = collectZeroInDegreeVertices(inDegree);
 39	        List<Integer> sortedVertices = new ArrayList<>(vertexCount);
 40	
 41	        while (!readyVertices.isEmpty()) {
 42	            int vertex = readyVertices.removeFirst();
 43	            sortedVertices.add(vertex);
 44	            enqueueReadyNeighbors(adjacencyList.get(vertex), inDegree, readyVertices);
 45	        }
 46	
 47	        return sortedVertices;
 48	    }
 49	
 50	    static void addEdge(List<? extends List<Integer>> adjacencyList, int from, int to) {
 51	        adjacencyList.get(from).add(to);
 52	    }
 53	
 54	    private static void addEdge(List<? extends List<Integer>> adjacencyList, Edge edge) {
 55	        addEdge(adjacencyList, edge.from, edge.to);
 56	    }
 57	
 58	    private static Edge edge(int from, int to) {
 59	        return new Edge(from, to);
 60	    }
 61	
 62	    private static List<List<Integer>> buildSampleGraph() {
 63	        return buildGraph(SAMPLE_VERTEX_COUNT, SAMPLE_EDGES);
 64	    }
 65	
 66	    private static List<List<Integer>> buildGraph(int vertexCount, Edge[] edges) {
 67	        List<List<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
 68	        for (Edge edge : edges) {
 69	            addEdge(adjacencyList, edge);
 70	        }
 71	        return adjacencyList;
 72	    }
 73	
 74	    private static int[] calculateInDegrees(List<? extends List<Integer>> adjacencyList) {
 75	        int[] inDegree = new int[adjacencyList.size()];
 76	        for (List<Integer> neighbors : adjacencyList) {
 77	            for (int neighbor : neighbors) {
 78	                inDegree[neighbor]++;
 79	            }
 80	        }
 81	        return inDegree;
 82	    }
 83	
 84	    private static Deque<Integer> collectZeroInDegreeVertices(int[] inDegree) {
 85	        Deque<Integer> readyVertices = new ArrayDeque<>();
 86	        for (int vertex = 0; vertex < inDegree.length; vertex++) {
 87	            if (inDegree[vertex] == 0) {
 88	                readyVertices.addLast(vertex);
 89	            }
 90	        }
 91	        return readyVertices;
 92	    }
 93	
 94	    private static void enqueueReadyNeighbors(
 95	            List<Integer> neighbors,
 96	            int[] inDegree,
 97	            Deque<Integer> readyVertices
 98	    ) {
 99	        for (int neighbor : neighbors) {
100	            inDegree[neighbor]--;
101	            if (inDegree[neighbor] == 0) {
102	                readyVertices.addLast(neighbor);
103	            }
104	        }
105	    }
106	
107	    private static List<List<Integer>> createEmptyAdjacencyList(int vertexCount) {
108	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
109	        for (int vertex = 0; vertex < vertexCount; vertex++) {
110	            adjacencyList.add(new ArrayList<>());
111	        }
112	        return adjacencyList;
113	    }
114	
115	    private static void printVertices(List<Integer> vertices) {
116	        System.out.println(formatVertices(vertices));
117	    }
118	
119	    private static String formatVertices(List<Integer> vertices) {
120	        StringBuilder output = new StringBuilder();
121	        for (int vertex : vertices) {
122	            output.append(vertex).append(' ');
123	        }
124	        return output.toString();
125	    }
126	
127	    public static void main(String[] args) {
128	        List<List<Integer>> adjacencyList = buildSampleGraph();
129	        List<Integer> sortedVertices = topologicalSort(adjacencyList);
130	        printVertices(sortedVertices);
131	    }
132	}

